using ASMILE.BO.Shared.Foundation;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

namespace ASMILE.BO.App.ViewModels;

public sealed partial class HotelDepositPolicyViewModel : ViewModelBase
{
    private readonly IHotelStructureMasterDataRepository? _repository; private readonly IFrontOfficeExecutionContextAccessor? _contextAccessor; private readonly CreateHotelDepositPolicyCommandHandler? _create; private readonly UpdateHotelDepositPolicyCommandHandler? _update; private readonly ActivateHotelDepositPolicyCommandHandler? _activate; private readonly DeactivateHotelDepositPolicyCommandHandler? _deactivate; private bool _initialized;
    public HotelDepositPolicyViewModel(IHotelStructureMasterDataRepository? repository = null, IFrontOfficeExecutionContextAccessor? contextAccessor = null, CreateHotelDepositPolicyCommandHandler? create = null, UpdateHotelDepositPolicyCommandHandler? update = null, ActivateHotelDepositPolicyCommandHandler? activate = null, DeactivateHotelDepositPolicyCommandHandler? deactivate = null) { _repository = repository; _contextAccessor = contextAccessor; _create = create; _update = update; _activate = activate; _deactivate = deactivate; }
    public ObservableCollection<HotelDepositPolicyDto> Items { get; } = [];
    public IReadOnlyList<string> TypeOptions { get; } = ["Phần trăm", "Số tiền cố định", "Đêm đầu", "Toàn bộ kỳ lưu trú", "Thủ công"];
    [ObservableProperty] private HotelDepositPolicyDto? selectedItem; [ObservableProperty] private string searchText = string.Empty; [ObservableProperty] private bool isLoading; [ObservableProperty] private bool isEditing; [ObservableProperty] private string depositType = "Phần trăm"; [ObservableProperty] private string code = string.Empty; [ObservableProperty] private string name = string.Empty; [ObservableProperty] private bool required = true; [ObservableProperty] private string percentage = "30"; [ObservableProperty] private string fixedAmount = "0"; [ObservableProperty] private string dueDaysBeforeArrival = "7"; [ObservableProperty] private bool refundable = true; [ObservableProperty] private bool transferable; [ObservableProperty] private bool forfeitable = true; [ObservableProperty] private bool autoReminder = true; [ObservableProperty] private bool autoApplyToFolio = true; [ObservableProperty] private string effectiveFrom = DateTime.Today.ToString("yyyy-MM-dd"); [ObservableProperty] private string effectiveTo = DateTime.Today.AddYears(1).ToString("yyyy-MM-dd"); [ObservableProperty] private string description = string.Empty; [ObservableProperty] private string errorMessage = string.Empty; [ObservableProperty] private string infoMessage = string.Empty;
    public bool HasError => !string.IsNullOrWhiteSpace(ErrorMessage); public bool HasInfo => !string.IsNullOrWhiteSpace(InfoMessage); public bool IsReadOnlyPanelVisible => !IsEditing; public string SelectedSummary => SelectedItem is null ? "Chọn chính sách để xem và chỉnh sửa." : $"{SelectedItem.Code} · {SelectedItem.Name}"; public string SelectedStatus => SelectedItem?.IsActive == true ? "Đang sử dụng" : "Tạm ngưng"; public string SelectedTypeLabel => SelectedItem is null ? "-" : TypeLabel(SelectedItem.DepositType);
    public async Task InitializeAsync(CancellationToken ct) { if (_initialized) return; _initialized = true; await LoadAsync(ct); }
    [RelayCommand] private async Task LoadAsync(CancellationToken ct) { IsLoading = true; ErrorMessage = string.Empty; try { if (_repository is null || _contextAccessor?.Current?.Property.PropertyId.Value is not { } propertyId || propertyId == Guid.Empty) { ErrorMessage = "Chưa có kết nối dữ liệu hoặc property context."; return; } var result = await _repository.SearchDepositPoliciesAsync(propertyId, string.IsNullOrWhiteSpace(SearchText) ? null : SearchText.Trim(), null, new PageRequest(1, 200), "effective", ct); Items.Clear(); foreach (var item in result.Items) Items.Add(item); if (SelectedItem is null || Items.All(x => x.HotelDepositPolicyId != SelectedItem.HotelDepositPolicyId)) SelectedItem = Items.FirstOrDefault(); InfoMessage = $"Đã tải {Items.Count} chính sách đặt cọc từ dữ liệu thật."; } catch (OperationCanceledException) when (ct.IsCancellationRequested) { } catch (Exception ex) { ErrorMessage = $"Không tải được chính sách đặt cọc: {ex.Message}"; } finally { IsLoading = false; RaiseState(); } }
    [RelayCommand] private Task SearchAsync(CancellationToken ct) => LoadAsync(ct);
    [RelayCommand] private void NewItem() { SelectedItem = null; DepositType = "Phần trăm"; Code = string.Empty; Name = string.Empty; Required = true; Percentage = "30"; FixedAmount = "0"; DueDaysBeforeArrival = "7"; Refundable = true; Transferable = false; Forfeitable = true; AutoReminder = true; AutoApplyToFolio = true; EffectiveFrom = DateTime.Today.ToString("yyyy-MM-dd"); EffectiveTo = DateTime.Today.AddYears(1).ToString("yyyy-MM-dd"); Description = string.Empty; IsEditing = true; RaiseState(); }
    [RelayCommand] private void EditItem() { if (SelectedItem is null) return; Fill(SelectedItem); IsEditing = true; RaiseState(); } [RelayCommand] private void CancelEdit() { IsEditing = false; RaiseState(); }
    [RelayCommand] private async Task SaveAsync(CancellationToken ct) { ErrorMessage = string.Empty; if (!TryType(DepositType, out var type) || !decimal.TryParse(Percentage, out var pct) || !decimal.TryParse(FixedAmount, out var amount) || !int.TryParse(DueDaysBeforeArrival, out var due) || !DateTime.TryParse(EffectiveFrom, out var from) || !DateTime.TryParse(EffectiveTo, out var to)) { ErrorMessage = "Loại, số tiền, ngày đến hạn hoặc hiệu lực không hợp lệ."; RaiseState(); return; } try { Result<HotelDepositPolicyDto> result; if (SelectedItem is null) { if (_create is null) { ErrorMessage = "Chưa đăng ký command cấu hình thật."; return; } result = await _create.HandleAsync(new CreateHotelDepositPolicyCommand(Code, Name, type, Required, pct, amount, due, Refundable, Transferable, Forfeitable, AutoReminder, AutoApplyToFolio, from, to, NullIfEmpty(Description)), ct); } else { if (_update is null) { ErrorMessage = "Chưa đăng ký command cấu hình thật."; return; } result = await _update.HandleAsync(new UpdateHotelDepositPolicyCommand(SelectedItem.HotelDepositPolicyId, Code, Name, type, Required, pct, amount, due, Refundable, Transferable, Forfeitable, AutoReminder, AutoApplyToFolio, from, to, NullIfEmpty(Description), SelectedItem.RowVersion ?? []), ct); } if (result.IsFailure) { ErrorMessage = result.Error?.Message ?? "Không lưu được cấu hình."; return; } InfoMessage = "Đã lưu chính sách đặt cọc vào dữ liệu thật."; IsEditing = false; await LoadAsync(ct); } catch (Exception ex) { ErrorMessage = $"Không lưu được cấu hình: {ex.Message}"; } finally { RaiseState(); } }
    [RelayCommand] private async Task ToggleActiveAsync(CancellationToken ct) { if (SelectedItem is null) return; var result = SelectedItem.IsActive ? _deactivate is null ? Missing() : await _deactivate.HandleAsync(new DeactivateHotelDepositPolicyCommand(SelectedItem.HotelDepositPolicyId, SelectedItem.RowVersion ?? []), ct) : _activate is null ? Missing() : await _activate.HandleAsync(new ActivateHotelDepositPolicyCommand(SelectedItem.HotelDepositPolicyId, SelectedItem.RowVersion ?? []), ct); if (result.IsFailure) { ErrorMessage = result.Error?.Message ?? "Không đổi được trạng thái."; RaiseState(); return; } await LoadAsync(ct); }
    private void Fill(HotelDepositPolicyDto x) { DepositType = TypeLabel(x.DepositType); Code = x.Code; Name = x.Name; Required = x.Required; Percentage = x.Percentage.ToString("0.####"); FixedAmount = x.FixedAmount.ToString("0.##"); DueDaysBeforeArrival = x.DueDaysBeforeArrival.ToString(); Refundable = x.Refundable; Transferable = x.Transferable; Forfeitable = x.Forfeitable; AutoReminder = x.AutoReminder; AutoApplyToFolio = x.AutoApplyToFolio; EffectiveFrom = x.EffectiveFrom.ToString("yyyy-MM-dd"); EffectiveTo = x.EffectiveTo.ToString("yyyy-MM-dd"); Description = x.Description ?? string.Empty; }
    private static bool TryType(string value, out HotelDepositType type) { type = value switch { "Số tiền cố định" => HotelDepositType.FixedAmount, "Đêm đầu" => HotelDepositType.FirstNight, "Toàn bộ kỳ lưu trú" => HotelDepositType.FullStay, "Thủ công" => HotelDepositType.Manual, _ => HotelDepositType.Percentage }; return value is not ""; } private static string TypeLabel(HotelDepositType type) => type switch { HotelDepositType.FixedAmount => "Số tiền cố định", HotelDepositType.FirstNight => "Đêm đầu", HotelDepositType.FullStay => "Toàn bộ kỳ lưu trú", HotelDepositType.Manual => "Thủ công", _ => "Phần trăm" }; private static string? NullIfEmpty(string value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim(); private static Result<HotelDepositPolicyDto> Missing() => Result<HotelDepositPolicyDto>.Failure(Error.System("HOTEL_DEPOSIT_COMMAND_MISSING", "Command is unavailable.")); private void RaiseState() { OnPropertyChanged(nameof(HasError)); OnPropertyChanged(nameof(HasInfo)); OnPropertyChanged(nameof(IsReadOnlyPanelVisible)); OnPropertyChanged(nameof(SelectedSummary)); OnPropertyChanged(nameof(SelectedStatus)); OnPropertyChanged(nameof(SelectedTypeLabel)); } partial void OnSelectedItemChanged(HotelDepositPolicyDto? value) { if (!IsEditing && value is not null) Fill(value); RaiseState(); }
}
